import itertools
import numpy as np


class RacingHalvingEDA:
    """
    Mixed-variable EDA with successive-halving racing over discrete configurations.
    Every discrete configuration keeps its best observed point. After a full sweep,
    the top configurations are raced: each gets a short momentum pattern search, and
    the better half survives to a doubled budget. The pattern search adds random
    discrete pair flips when stalled. The EDA (elite crossover, DE moves, never-re-spend
    cache) runs between restarts that cycle through global, shrinking-local and kick sampling.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        dim = self.dim
        budget = self.budget

        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        vtypes = list(func.variable_types)
        disc = np.array([i for i in range(dim) if vtypes[i] != "continuous"], dtype=int)
        cont = np.array([i for i in range(dim) if vtypes[i] == "continuous"], dtype=int)

        nvals = np.ones(dim, dtype=int)
        for i in disc:
            nvals[i] = int(round(func.n_values[i]))
        rng_w = ub - lb

        used = 0
        cap = budget          # soft cap used by racing phases
        best_y = np.inf
        best_x = None
        cache = {}
        cfg_best = {}         # discrete configuration -> [y, x]
        polished_cfg = set()

        def row_key(x):
            k = []
            for i in range(dim):
                if vtypes[i] == "continuous":
                    k.append(round(float(x[i]), 10))
                else:
                    k.append(int(round(float(x[i]))))
            return tuple(k)

        def dkey(x):
            return tuple(int(round(float(x[i]))) for i in disc)

        def evaluate(X):
            nonlocal used, best_y, best_x
            n = X.shape[0]
            Y = np.full(n, np.inf)
            pending = {}
            for idx in range(n):
                k = row_key(X[idx])
                if k in cache:
                    Y[idx] = cache[k]
                else:
                    pending.setdefault(k, []).append(idx)
            if pending:
                rem = max(0, min(budget, cap) - used)
                ks = list(pending.keys())[:rem]
                if ks:
                    Xn = np.array([X[pending[k][0]] for k in ks])
                    Yn = np.asarray(func(Xn), dtype=float).ravel()
                    used += len(ks)
                    for k, yv in zip(ks, Yn):
                        cache[k] = float(yv)
                        xr = X[pending[k][0]].copy()
                        for idx in pending[k]:
                            Y[idx] = yv
                        dk = dkey(xr)
                        if dk not in cfg_best or yv < cfg_best[dk][0]:
                            cfg_best[dk] = [float(yv), xr.copy()]
                        if yv < best_y:
                            best_y = float(yv)
                            best_x = xr.copy()
            return Y

        def sample(n):
            X = np.empty((n, dim))
            if len(cont):
                X[:, cont] = np.random.uniform(lb[cont], ub[cont], size=(n, len(cont)))
            for i in disc:
                X[:, i] = np.random.randint(0, nvals[i], size=n)
            return X

        def repair(X):
            if len(cont):
                X[:, cont] = np.clip(X[:, cont], lb[cont], ub[cont])
            for i in disc:
                X[:, i] = np.clip(np.rint(X[:, i]), 0, nvals[i] - 1)
            return X

        def local_sample(n, r, pflip=0.3):
            X = np.repeat(best_x[None, :], n, axis=0).astype(float)
            if len(cont):
                X[:, cont] += np.random.randn(n, len(cont)) * r * rng_w[cont]
            for i in disc:
                flip = np.random.rand(n) < pflip
                X[flip, i] = np.random.randint(0, nvals[i], size=int(flip.sum()))
            return repair(X)

        def kick(n, r):
            X = np.repeat(best_x[None, :], n, axis=0).astype(float)
            if len(cont):
                X[:, cont] += np.random.randn(n, len(cont)) * r * rng_w[cont]
            for row in range(n):
                if len(disc):
                    nk = 1 + np.random.randint(min(3, len(disc)))
                    for i in np.random.choice(disc, size=nk, replace=False):
                        X[row, i] = np.random.randint(0, nvals[i])
            return repair(X)

        def sweep_points():
            if len(disc) == 0:
                return None
            total = float(np.prod([float(nvals[i]) for i in disc]))
            if total > 0.25 * budget:
                return None
            combos = list(itertools.product(*[range(nvals[i]) for i in disc]))
            X = sample(len(combos))
            for r, c in enumerate(combos):
                X[r, disc] = c
            return X

        def polish(base, yb, rounds):
            """Momentum pattern search with per-coordinate steps; pair flips when stalled."""
            cur = np.asarray(base, dtype=float).copy()
            cy = float(yb)
            st = np.full(len(cont), 0.1)
            mom = np.zeros(dim)
            stall = 0
            for _ in range(rounds):
                if used >= min(budget, cap):
                    break
                cands, tags = [], []
                for i in disc:
                    b = int(round(cur[i]))
                    if vtypes[i] == "binary":
                        vals = [1 - b]
                    elif vtypes[i] == "ordinal":
                        vals = [b - 1, b + 1, b - 2, b + 2]
                    else:
                        vals = [v for v in range(nvals[i]) if v != b]
                    for v in vals:
                        if 0 <= v < nvals[i]:
                            x = cur.copy()
                            x[i] = v
                            cands.append(x)
                            tags.append(('d', -1, 0.0))
                if stall >= 2 and len(disc) >= 2:
                    for _p in range(3):
                        x = cur.copy()
                        pair = np.random.choice(disc, size=2, replace=False)
                        for i in pair:
                            x[i] = np.random.randint(0, nvals[i])
                        cands.append(x)
                        tags.append(('p', -1, 0.0))
                for j, i in enumerate(cont):
                    for sg in (-1.0, 1.0):
                        x = cur.copy()
                        x[i] = cur[i] + sg * st[j] * rng_w[i]
                        cands.append(x)
                        tags.append(('c', j, sg))
                if np.any(mom != 0):
                    cands.append(cur + mom)
                    tags.append(('m', -1, 0.0))
                if not cands:
                    break
                Xc = repair(np.array(cands))
                Yc = evaluate(Xc)
                if not np.isfinite(Yc).any():
                    break
                k = int(np.argmin(Yc))
                if Yc[k] < cy - 1e-12:
                    new = Xc[k].copy()
                    kind, j, _ = tags[k]
                    if kind == 'c':
                        st[j] = min(st[j] * 1.5, 0.5)
                    mom = new - cur
                    cur = new
                    cy = float(Yc[k])
                    stall = 0
                else:
                    stall += 1
                    st *= 0.5
                    mom *= 0.3
                    if (len(cont) == 0 or st.max() < 1e-4) and stall >= 3:
                        break
            return cur, cy

        def race(limit_frac, init_rounds=4, keep_frac=0.5, top_k=4):
            """Successive halving over configuration elites."""
            nonlocal cap
            old_cap = cap
            cap = min(budget, used + int(limit_frac * budget))
            cand = [dk for dk, _ in sorted(cfg_best.items(), key=lambda kv: kv[1][0])[:top_k]]
            rounds = init_rounds
            while cand and used < cap:
                for dk in cand:
                    if used >= cap:
                        break
                    yv, xv = cfg_best[dk]
                    polish(xv, yv, rounds)
                    polished_cfg.add(dk)
                cand = sorted(cand, key=lambda d: cfg_best[d][0])
                cand = cand[:max(1, int(np.ceil(len(cand) * keep_frac)))]
                if len(cand) == 1 and rounds > 16:
                    break
                rounds *= 2
            cap = old_cap

        def elite_polish(rounds=10):
            """Polish the best not-yet-polished discrete configuration; fall back to incumbent."""
            if best_x is None:
                return
            cands = sorted(cfg_best.items(), key=lambda kv: kv[1][0])
            for dk, (yv, xv) in cands:
                if dk not in polished_cfg:
                    polished_cfg.add(dk)
                    polish(xv, yv, rounds)
                    return
            polish(best_x, best_y, rounds)

        def fresh_archive(n, mode, r=0.1):
            n_eff = max(1, min(n, budget - used))
            if mode == "local" and best_x is not None:
                X = local_sample(n_eff, r)
            elif mode == "kick" and best_x is not None:
                X = kick(n_eff, r)
            else:
                X = repair(sample(n_eff))
                if best_x is not None and n_eff > 0:
                    X[0] = best_x
            Y = evaluate(X)
            order = np.argsort(Y, kind="stable")[:mu]
            return X[order], Y[order]

        mu = max(6, dim)
        lam = max(8, dim)
        init_n = max(3 * mu, 20)
        p_explore = 0.1
        patience = 12

        restart_count = 0
        local_radius = 0.1
        kick_radius = 0.05

        Xs = sweep_points()
        if Xs is not None:
            Ys = evaluate(Xs)
            order = np.argsort(Ys, kind="stable")[:mu]
            Xa, Ya = Xs[order], Ys[order]
            # racing phase: spend up to ~30% of the budget on configuration elites
            race(0.30, init_rounds=4, keep_frac=0.5, top_k=4)
        else:
            Xa, Ya = fresh_archive(init_n, "global")
        if best_x is not None and used < budget:
            polish(best_x, best_y, 10)

        s = 1.0
        pd = 0.2
        gen_since = 0
        arch_best = best_y

        while used < budget and len(Xa) > 0:
            if gen_since >= patience:
                restart_count += 1
                mode_id = restart_count % 3
                if mode_id == 1:
                    Xa, Ya = fresh_archive(init_n, "global")
                elif mode_id == 2:
                    local_radius = max(0.01, local_radius * 0.6)
                    Xa, Ya = fresh_archive(init_n, "local", local_radius)
                else:
                    kick_radius = float(np.clip(kick_radius * np.random.choice([0.7, 1.4]), 0.01, 0.2))
                    Xa, Ya = fresh_archive(init_n, "kick", kick_radius)
                if used >= budget or len(Xa) == 0:
                    break
                elite_polish(10)
                s = 1.0
                pd = 0.2
                gen_since = 0
                arch_best = best_y
                if used >= budget or len(Xa) == 0:
                    break

            n = min(lam, budget - used)
            if n <= 0:
                break
            m = len(Xa)

            if len(cont):
                sd = Xa[:, cont].std(axis=0)
                sig = np.maximum(sd, 1e-3 * rng_w[cont]) * s

            probs = []
            for i in disc:
                cnt = np.bincount(Xa[:, i].astype(int), minlength=nvals[i]).astype(float)
                p = cnt + 0.5
                probs.append(p / p.sum())

            children = np.empty((n, dim))
            seen = set()
            for c in range(n):
                if m < 2 or np.random.rand() < p_explore:
                    x = sample(1)[0]
                else:
                    i1 = int(m * np.random.rand() ** 2)
                    x = Xa[i1].copy()

                    if np.random.rand() < 0.5:
                        i2 = np.random.randint(m)
                        mask = np.random.rand(dim) < 0.5
                        x[mask] = Xa[i2][mask]

                    if len(cont):
                        if m >= 3 and np.random.rand() < 0.3:
                            i2, i3 = np.random.choice(m, 2, replace=False)
                            F = np.random.uniform(0.4, 0.9)
                            x[cont] = Xa[i1][cont] + F * (Xa[i2][cont] - Xa[i3][cont])
                        else:
                            mk = np.random.rand(len(cont)) < 0.5
                            x[cont] += mk * np.random.randn(len(cont)) * sig

                    for j, i in enumerate(disc):
                        if np.random.rand() < pd:
                            if vtypes[i] == "ordinal":
                                if np.random.rand() < 0.6:
                                    x[i] = x[i] + (1 if np.random.rand() < 0.5 else -1)
                                else:
                                    x[i] = np.random.choice(nvals[i], p=probs[j])
                            elif vtypes[i] == "binary":
                                x[i] = 1 - x[i]
                            else:
                                x[i] = np.random.choice(nvals[i], p=probs[j])

                x = repair(x[None, :])[0]
                k = row_key(x)
                if k in cache or k in seen:
                    x = repair(sample(1))[0]
                    k = row_key(x)
                seen.add(k)
                children[c] = x

            Y = evaluate(children)

            Xall = np.vstack([Xa, children])
            Yall = np.concatenate([Ya, Y])
            order = np.argsort(Yall, kind="stable")[:mu]
            n_old = len(Xa)
            rate = np.sum(order >= n_old) / max(1, n)
            Xa, Ya = Xall[order], Yall[order]

            s = float(np.clip(s * np.exp(0.5 * (rate - 0.2)), 0.02, 3.0))
            if len(disc):
                pd = float(np.clip(pd * (1.1 if rate > 0.2 else 0.93), 0.05, 0.5))

            if best_y < arch_best - 1e-12:
                arch_best = best_y
                gen_since = 0
                if best_x is not None and used < budget:
                    polish(best_x, best_y, 8)
                arch_best = min(arch_best, best_y)
            else:
                gen_since += 1

        return best_y, best_x
